e editor settings and scene restored",r.id);break;case "releaseSetup":ReleaseFoundationSetup.Setup();Write("saved","Release config and Korean documents bound",r.id);break;case "releaseValidate":ReleaseFoundationSetup.Validate();Write("audited","Release validation saved",r.id);break;case "releaseAndroid":ReleasePlatformBuild.Begin(BuildTarget.Android);Write("queued","Android signing preflight checked",r.id);break;case "releaseIOS":ReleasePlatformBuild.Begin(BuildTarget.iOS);Write("queued","iOS export attempt queued",r.id);break;case "info":Write("ready","Unity "+Application.unityVersion,r.id);break;case "build":LifeWorldBuilder.Build();Write("built","LifeWorld scene, catalog, GameContext and UI saved",r.id);break;case "roomVisualPhase31Gear":case "roomVisualPhase31Extended":case "roomVisualPhase31Before":case "roomVisualPhase31":case "roomVisualRelease":case "roomVisualGrowthCare":case "roomVisualGrowthBed":case "roomVisualGrowthPreview":case "roomVisualGrowthDoors":case "roomVisualGrowthMeals":case "roomVisualGrowthQA":case "roomVisualGrowthSave":case "roomVisualGrowth":case "roomVisualGrowthLife":case "roomVisualArchitecture":case "roomVisualBefore":case "roomVisualPolish":case "roomVisualCycles":case "roomVisualCheck":case "roomVisualShower":case "roomVisualDoors":case "roomVisualMobile":case "sceneMeal":case "sceneCapture":case "sceneFinal":case "sceneHousing":case "sceneRegistry":case "sceneCheck":case "sceneDoors":case "sceneState":case "familyInteraction":case "familyArchitecture":case "familyHousehold":case "familyCheck":case "familyActions":case "familyDoors":case "facilityCompanyShift":case "facilityClerkExit":case "facilityTerminals":case "facilityActorsRemaining":case "facilityCaptureAfter":case "facilityActors":case "facilityFunctions":case "facilityRegistry":case "facilityMobile":case "facilityCheck":case "facilityCaptureBefore":case "pre28SaveGuard":case "pre28DoorRetest":case "pre28World":case "pre28Walking":case "pre28Growth":case "pre28UI":case "pre